    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const existing = ['INV-2026-0001', 'INV-2026-0005'];
  const r2 = issueInvoice(inv, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0006');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoice', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  const r = issueInvoice(inv, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const originalStatus = inv.status;

  issueInvoice(inv, []);
  assert.equal(inv.status, originalStatus);
  assert.equal(inv.number, undefined);
});

